#!/usr/bin/env python3
"""Renderiza uma apresentação local, com dados embutidos e sem dependências de rede."""
import html,json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def generate(rows,data,stats):
    def slide(k,title,body,note,cls=''):
        return f'<section class="slide {cls}" aria-labelledby="s{k}" data-title="{html.escape(title)}"><div class="eyebrow">DCC136 · {k:02d} / 12</div><h2 id="s{k}">{title}</h2>{body}<aside class="notes"><strong>Roteiro · </strong>{note}</aside></section>'
    slides=[]
    slides.append(slide(1,'Locais de prova.<br><em>Decisões que aproximam.</em>', '''<p class="lede">Construção gulosa randomizada, VND e Busca Tabu<br>para alocar candidatos com capacidade e compatibilidade.</p><div class="coverline"><span>Bruno Keil · UFJF<br>Inteligência Computacional · 2026.3</span><span>28 instâncias<br>1.680 execuções · K = 1</span></div>''','0:00–0:35 · Apresentar o objetivo e os dois níveis de decisão: tipos nas escolas e destinos dos candidatos. O trabalho segue um tipo por escola.','cover'))
    slides.append(slide(2,'Uma escola. Um tipo.<br>Todos os candidatos possíveis.', '''<div class="split"><div><p class="lede">Minimizar a distância total percorrida, respeitando as vagas disponíveis.</p><div class="formula">D = Σ d(i, aᵢ)</div><p>Cada candidato tem um único destino compatível. A escola é utilizada quando recebe candidatos.</p></div><div class="rules"><div><b>01</b><span>Um tipo por escola<br><small>K = 1 no enunciado</small></span></div><div><b>02</b><span>Capacidade compartilhada<br><small>Soma das vagas das salas</small></span></div><div><b>03</b><span>Matriz de distâncias<br><small>Sem custo de abertura</small></span></div></div></div>''','0:35–1:15 · Motivar o problema de planejamento de exames. Os locais não têm tipo previamente fixado: nossa solução escolhe esse tipo. K=2 existe no programa apenas como extensão.'))
    slides.append(slide(3,'Uma solução em dois vetores.', '''<div class="split"><div><div class="caption">ESCOLA → TIPO HABILITADO</div><div class="vector"><span>E1<br><b>M2</b></span><span>E2<br><b>M1</b></span><span>E3<br><b>—</b></span></div><div class="caption">CANDIDATO → ESCOLA</div><div class="code">a = [E2, E2, E2, E2,<br>　　 E1, E1, E1, E1]</div></div><div><p class="lede">Cargas e distância são atualizadas a cada movimento.</p><p>Guardamos também carga por tipo, excesso e candidatos não alocados (<code>−1</code>).</p><p class="callout">Distâncias em inteiros de milionésimos de km: comparação exata até seis casas decimais.</p></div></div>''','1:15–1:50 · Explicar índices na ordem do arquivo, IDs preservados e capacidade agregada. O vetor exibido será usado no exemplo didático.'))
    slides.append(slide(4,'Antes de otimizar,<br>verificar se é possível.', '''<div class="split"><div><p class="lede">Um modelo inteiro pequeno certifica o atendimento máximo C*.</p><p>Maximiza contagens por escola e tipo, com limite de vagas, demanda e um tipo por escola.</p><div class="formula">1º atendimento · 2º distância</div></div><div class="callout"><div class="big">6 ≠ 5</div><h3>Seis tipos. Cinco escolas.</h3><p>G2/2 tem 109 candidatos e 121 vagas. Ainda assim, é inviável em K=1.</p><p>O resultado parcial é identificado e preserva o atendimento máximo certificado.</p></div></div><p class="footnote">SciPy/HiGHS certifica atendimento; não otimiza distâncias. Timeout é inconclusivo.</p>''','1:50–2:35 · Este é o caso em que não existe solução completa. Não atribuir a falha à heurística. Uma solução parcial de menor distância não deve ser comparada a uma solução completa.'))
    slides.append(slide(5,'Construir sem fechar<br>as próximas escolhas.', '''<div class="steps"><div><b>01 / Habilitar tipos</b><p>Combinar ganho de atendimento por fluxo, uso da capacidade e proximidade.</p><code>score = g/bₜ + g/Qⱼ − proximidade</code></div><div><b>02 / Alocar por regret</b><p>Priorizar quem perde mais ao abrir mão da melhor escola. Uma única opção vem primeiro.</p><code>regret = d₂ − d₁</code></div><div><b>03 / Reparar impasses</b><p>Caminhos aumentantes deslocam candidatos até alcançar uma vaga compatível.</p><code>candidato → escola → … → vaga</code></div></div><p class="callout">RCL com α = 0,3 varia as escolhas. Reparo de tipos, reinícios e tipos certificados fornecem uma salvaguarda.</p>''','2:35–3:30 · Justificar a prioridade a candidatos com poucas alternativas. Escolhas de tipos podem bloquear cobertura; explicitar que o certificado também pode fornecer os tipos no fallback.'))
    slides.append(slide(6,'Três formas de mudar<br>a mesma solução.', '''<div class="steps neighborhoods"><div><span class="nmark">N1</span><h3>Realocar</h3><p>Um candidato muda de escola compatível.</p><code>Δ = dᵢᵦ − dᵢₐ</code><p class="muted">Até cinco destinos próximos.</p></div><div><span class="nmark">N2</span><h3>Trocar</h3><p>Dois candidatos do mesmo tipo permutam destinos.</p><code>Δ = dᵢᵦ + dₕₐ − dᵢₐ − dₕᵦ</code><p class="muted">Preserva cargas das escolas.</p></div><div><span class="nmark">N3</span><h3>Mudar tipos</h3><p>Adicionar, substituir ou permutar tipos; reconstruir alocações afetadas.</p><p class="muted">Fluxo filtra perda de atendimento. Seis reconstruções por chamada.</p></div></div>''','3:30–4:20 · N1/N2 atuam nos destinos. N3 muda a estrutura. A correção reconsidera candidatos dos tipos recém-habilitados para poder ocupar uma escola antes vazia.'))
    slides.append(slide(7,'Descer ou atravessar<br>um vale de piora.', '''<div class="split method"><div><span class="tag green">VND</span><h3>Aceitar melhora estrita.</h3><p>N1 → N2 → N3.<br>Após melhora, voltar à N1.</p><p>Melhor melhoria entre os movimentos examinados.</p></div><div><span class="tag red">BUSCA TABU</span><h3>Explorar além da descida.</h3><p>Escolher o melhor movimento admissível, mesmo com piora temporária.</p><p>Memória tabu [5,12], aspiração e arquivo da melhor solução.</p></div></div><div class="formula smallformula">f(s) = D(s) + λ · excesso + μ · (não alocados + incompatíveis)</div><p class="footnote">Penalidades iniciais dominam a distância; λ adapta na tabu. A solução devolvida preserva capacidade e atendimento certificado.</p>''','4:20–5:10 · Explicar tabu como prevenção de retorno imediato, aspiração pela melhor completa viável e adaptação de λ a cada cinco estados. Na campanha: 150 iterações ou 50 sem melhora, tempo desativado.'))
    slides.append(slide(8,'Um local vazio pode<br>guardar uma melhoria.', '''<div class="example-toolbar"><span class="tag green">EXEMPLO · 8 CANDIDATOS · K=1</span><button id="example-toggle" type="button">Aplicar N3 →</button></div><div class="split example"><div><div class="caption" id="example-caption">CONSTRUÇÃO · E1/M2 E E2/M1</div><div id="school-demo"></div></div><div><div class="big" id="example-cost">56 <small>km</small></div><p class="lede" id="example-description">O construtivo atende todos com E1 e E2. E3 permanece vazia.</p><p>N1 e N2 não melhoram esses tipos fixos. N3 habilita M1 em E3.</p><p class="footnote">Demonstração com α=0 e até 1000 reconstruções, para examinar todas as propostas do exemplo.</p></div></div>''','5:10–6:25 · Clique em Aplicar N3. Inicial: M1 em E2 custa 33; M2 em E1 custa 23. Habilitar M1 em E3 libera candidatos M1. C3 tem regret 10 e C1 regret 4: ocupam E3. M1 passa a custar 19, total 42; melhora 25%. Capacidades 4,4,2. Este é o exemplo K=1, não o antigo exemplo K=2.'))
    slides.append(slide(9,'O que limita a qualidade.', '''<div class="split"><div><span class="tag red">FALHA HEURÍSTICA</span><h3>Viável ainda pode ser ruim.</h3><p>Os 56 km do exemplo atendem todos, mas deixam uma escola próxima sem uso. Uma N3 amostrada pode perder a proposta que leva a 42 km.</p><p>Limites de iterações e listas de candidatos também restringem a exploração.</p></div><div><span class="tag green">CORREÇÃO DA IMPLEMENTAÇÃO</span><h3>Habilitar precisa realocar.</h3><p>A versão anterior mantinha os candidatos nas escolas inalteradas. A escola nova não recebia ninguém.</p><p>Agora os candidatos dos tipos recém-habilitados são reconsiderados. Um teste protege esse comportamento.</p></div></div><p class="callout">Encerrar a busca não prova ótimo local da vizinhança completa nem ótimo global.</p>''','6:25–7:10 · Distinguir limite de exploração, falha de implementação corrigida e inviabilidade estrutural. Não apresentar o custo 42 como ótimo global do problema completo.'))
    slides.append(slide(10,'Resultados que podem<br>ser conferidos.', f'''<div class="metricline"><div><b>28</b><span>instâncias distintas</span></div><div><b>30</b><span>sementes por método</span></div><div><b>3.360</b><span>soluções validadas</span></div><div><b>{stats['feasible']}</b><span>instâncias viáveis</span></div></div><div class="result-toolbar"><label for="instance-select">Explorar instância</label><select id="instance-select"></select><span id="result-status" class="tag"></span></div><div id="results-table" class="tablewrap"></div><p class="footnote">Km; média ± desvio padrão amostral. Tempos médios de busca em máquina compartilhada. Melhorias: média dos percentuais por execução. K=1 em todas as linhas.</p>''','7:10–8:20 · Mostrar G1/1, G2/2 e uma instância grande no seletor. Explicar dispersão entre sementes, custo inicial versus final e tempo. Soluções parciais só são comparadas com o mesmo atendimento.'))
    slides.append(slide(11,'A trajetória também<br>explica o resultado.', f'''<div class="split"><div id="convergence-chart"></div><div><p class="lede">Tabu com menor distância média em {stats['wins']} das 28 instâncias.</p><p>VND com menor média em {stats['vnd_wins']}; {stats['ties']} empates.</p><p>O mesmo limite de iterações não representa o mesmo tempo ou o mesmo número de avaliações.</p><p class="callout">Comparação descritiva. Sem alegação de significância ou superioridade universal.</p></div></div><p class="footnote">G1/1 · Melhor distância média por iteração. Curvas encerradas mantêm o último valor.</p>''','8:20–9:10 · Ler a curva como melhor solução arquivada, não custo do estado corrente. Mostrar diferenças de velocidade e qualidade sob orçamento. Processos paralelos tornam os tempos apenas indicativos.'))
    slides.append(slide(12,'Construir. Reparar.<br><em>Reconsiderar os tipos.</em>', '''<div class="split"><div><p class="lede">A decisão estrutural pode bloquear melhorias simples de alocação.</p><p>Certificar atendimento separa impossibilidade de falha heurística. Validar cada solução torna os resultados auditáveis.</p><p>Próximos passos: amostragem adaptativa em N3 e comparação por tempo e avaliações.</p></div><div class="closing"><div class="caption">ENTREGA REPRODUZÍVEL</div><p>C++17 + testes<br>LaTeX + PDF em formato SBC<br>Instâncias e resultados completos<br>Esta apresentação HTML offline</p><a href="relatorio.pdf">Abrir relatório ↗</a><br><a href="../resultados/final_resumo.csv">Abrir resultados CSV ↗</a></div></div><p class="footnote">Referência do enunciado: Oliveira (2021), PUC-Rio · SciPy/HiGHS para pré-checagem. Detalhes e parâmetros no relatório.</p>''','9:10–10:00 · Concluir com o papel de cada componente e limitações. Abrir para perguntas. O pacote contém código, relatório e os dados para reprodução.'))
    compact={}
    for r in rows:compact.setdefault(r['instance'],{})[r['method']]=r
    curves={}
    for method in ('vnd','tabu'):
        cs=[]
        for r in data['Instancia1_G1.txt',method]['runs']:
            by={int(p[0]):p[1] for p in r['convergence']};last=r['initial']['distance'];c=[]
            for i in range(151):last=by.get(i,last);c.append(last)
            cs.append(c)
        curves[method]=[statistics.mean(c[i] for c in cs) for i in range(151)]
    template=(ROOT/'docs/apresentacao_template.html').read_text()
    output=template.replace('<!-- SLIDES -->','\n'.join(slides)).replace('/* RESULTS */',json.dumps(compact,ensure_ascii=False).replace('</','<\\/')).replace('/* CURVES */',json.dumps(curves))
    (ROOT/'docs/apresentacao.html').write_text(output)
